import {createCodeEditor} from './code-editor.js';
import {projectFiles,mainFile,fileContent,setFileContent} from './source-files.js';
import {mergeSourceFiles,includeLinks} from './ide-project.js';
import {readZip} from './zip-reader.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function installWorkbench({getProject,getActive,editor,openSource,commit,invalidate,showDialog,closeDialog,onError}){
 const primary=document.getElementById('editor'),container=document.createElement('div');container.id='ide-editors';primary.before(container);container.append(primary);
 const second=document.createElement('section');second.id='ide-secondary';second.hidden=true;second.innerHTML='<label>İkinci dosya <select aria-label="İkinci düzenleyici dosyası"></select></label><div id="ide-second-editor"></div>';container.append(second);
 let secondFile=null,lastProject=null;
 const secondary=createCodeEditor(second.querySelector('div'),'',value=>{if(!secondFile)return;setFileContent(getProject(),secondFile,value);invalidate();},()=>{});
 const tools=document.createElement('div');tools.className='ide-toolbar';tools.innerHTML='<button id="ide-import">Dosya / kütüphane al</button><button id="ide-split" aria-pressed="false">Yan yana</button><button id="ide-goto">Satıra git</button><button id="ide-mark" title="F9 - satır işareti, firmware breakpoint değildir">◆ İşaret</button><button id="ide-includes">Bağlantılar</button>';container.before(tools);
 const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='.c,.cpp,.h,.hpp,.ino,.py,.zip';input.hidden=true;tools.append(input);
 tools.querySelector('#ide-import').onclick=()=>input.click();
 input.onchange=async()=>{try{const entries=[],skipped=[];let total=0;for(const f of input.files){total+=f.size;if(total>2*1024*1024)throw Error('İçe aktarma en fazla 2 MB olabilir.');if(f.name.toLowerCase().endsWith('.zip')){let archive=[...await readZip(new Uint8Array(await f.arrayBuffer()))];const root=archive[0]?.[0]?.split('/')[0];if(root&&archive.every(([n])=>n.startsWith(root+'/')))archive=archive.map(([n,t])=>[n.slice(root.length+1),t]);for(const[n,t]of archive){if(/\.(c|cpp|h|hpp|ino|py)$/.test(n))entries.push({name:n,content:t});else skipped.push(n);}}else entries.push({name:f.name,content:await f.text()});}if(!entries.length)throw Error('Arşivde desteklenen kaynak dosyası bulunamadı.');showDialog('Kaynak / kütüphane içe aktar',`<p>Dosyalar derleyiciye birlikte verilir. Hazır SDK ile uyumlu C/C++ kaynaklarını seçin; masaüstü kütüphaneleri kendiliğinden uyumlu hale gelmez.</p><pre class="json-preview">${entries.map(f=>esc(f.name)).join('\n')}</pre><label>Hedef klasör (isteğe bağlı)<input id="ide-prefix" placeholder="lib/lcd"></label><label class="ide-replace"><input type="checkbox" id="ide-replace"> Aynı adlı dosyaların içeriğini değiştir</label><p>${skipped.length?esc(skipped.length+' kaynak dışı dosya atlandı (belgeler / metadata).'):''}</p><p>Örnek bağlantı: <code>#include "lib/lcd/lcd.h"</code>. .c / .cpp dosyaları ayrıca derlenir; .c dosyasını #include etmeyin. Ana dosya ${esc(mainFile(getProject()))} olarak kalır. En fazla 16 kaynak / toplam 100 KB.</p><button id="ide-apply">Dosyaları projeye ekle</button><p id="ide-import-error" role="status"></p>`);document.getElementById('ide-apply').onclick=()=>{try{const files=mergeSourceFiles(getProject(),entries,{prefix:document.getElementById('ide-prefix').value.trim(),replace:document.getElementById('ide-replace').checked});commit(files);closeDialog();}catch(e){document.getElementById('ide-import-error').textContent=e.message;}};}catch(e){onError(e.message);}finally{input.value='';}};
 tools.querySelector('#ide-split').onclick=()=>{if(second.hidden&&projectFiles(getProject()).length<2)return onError('Yan yana görünüm için en az iki kaynak dosyası ekleyin.');second.hidden=!second.hidden;tools.querySelector('#ide-split').setAttribute('aria-pressed',String(!second.hidden));container.classList.toggle('split',!second.hidden);render();};
 tools.querySelector('#ide-goto').onclick=()=>{showDialog('Satır ve sütuna git','<form id="ide-location"><label>Satır <input name="line" type="number" min="1" value="1" required></label><label>Sütun <input name="column" type="number" min="1" value="1" required></label><button>Git</button></form>');document.getElementById('ide-location').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);closeDialog();editor.goToLine(Number(data.get('line')),Number(data.get('column')));};};
 tools.querySelector('#ide-mark').onclick=()=>editor.toggleBookmark();
 tools.querySelector('#ide-includes').onclick=()=>{const links=includeLinks(getProject(),getActive()),marks=editor.getBookmarks();showDialog('Dosya bağlantıları ve satır işaretleri',(links.length?links.map((l,i)=>'<p><button data-include="'+i+'" '+(!l.file?'disabled':'')+'>'+esc(l.header)+'</button> '+(l.file?esc(l.file):'SDK / harici başlık: yerel kaynak bulunmadı')+'</p>').join(''):'<p>Bu dosyada #include satırı yok.</p>')+'<p>◆ İşaretler gezinme içindir; çalışmayı durdurmaz.</p>'+marks.map(n=>'<button data-line="'+n+'">Satır '+n+'</button>').join(''));document.querySelectorAll('[data-include]').forEach(b=>b.onclick=()=>{openSource(links[Number(b.dataset.include)].file);closeDialog();});document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{closeDialog();editor.goToLine(Number(b.dataset.line));});};
 second.querySelector('select').onchange=e=>{secondFile=e.target.value;secondary.setFile(secondFile,fileContent(getProject(),secondFile));secondary.setLanguage(getProject().language||'arduino');};
 function render(){const project=getProject();if(project!==lastProject){lastProject=project;editor.resetFiles();secondary.resetFiles();secondFile=null;}editor.setFile(getActive(),fileContent(project,getActive())??project.code);const options=projectFiles(project).filter(f=>f.name!==getActive());if(!options.length){second.hidden=true;container.classList.remove('split');tools.querySelector('#ide-split').setAttribute('aria-pressed','false');return;}if(!options.some(f=>f.name===secondFile))secondFile=options[0].name;second.querySelector('select').innerHTML=options.map(f=>'<option '+(f.name===secondFile?'selected':'')+'>'+esc(f.name)+'</option>').join('');if(!second.hidden){secondary.setFile(secondFile,fileContent(project,secondFile));secondary.setLanguage(project.language||'arduino');}}
 return{render};
}
